mapper.select:
	SELECT 
  	REPORTTYPE AS reportType,
  	PROPERTYCODE AS propertyCode, 
 	BALANCE AS balance
	FROM CHB_MONTH_REPORT_DETAIL DETAIL
	WHERE DETAIL.REPORTUUID = (SELECT REPORTUUID FROM (
		SELECT ROW_NUMBER() OVER(PARTITION BY T.TERMID ORDER BY T.UPDATE_TIME DESC) RN,       
        	T.REPORTUUID,
        	T.TERMID
        	FROM CHB_MONTH_REPORT T

			where  T.org_code=#{org, jdbcType=VARCHAR}

		) WHERE RN = 1 AND TERMID = #{termId, jdbcType=VARCHAR}	
  	)

SELECT
REPORTTYPE AS reportType,
PROPERTYCODE AS propertyCode,
BOTTOMBALANCE AS balance
FROM CHB_MONTH_REPORT_DETAIL DETAIL
WHERE DETAIL.REPORTUUID = (SELECT REPORTUUID FROM (
SELECT ROW_NUMBER() OVER(PARTITION BY T.TERMID ORDER BY T.UPDATE_TIME DESC) RN,
T.REPORTUUID,
T.TERMID
FROM CHB_MONTH_REPORT T

	where  T.org_code=#{org, jdbcType=VARCHAR}

) WHERE RN = 1 AND TERMID = #{termId, jdbcType=VARCHAR}
)

SELECT A.VALCODE, sum(nvl(ASSETVALUE_A,0)) valueA, sum(nvl(ASSETVALUE_B,0)) valueB, sum(nvl(VALUEA_LAST,0)) valueALast, sum(nvl(VALUEB_LAST,0)) valueBLast, decode(sum(nvl(ASSETVALUE_A, 0)),0,0,SUM(avgRate1) / sum(nvl(ASSETVALUE_A, 0))) avgRate1, decode(sum(nvl(ASSETVALUE_B, 0)),0,0,SUM(avgRate2) / sum(nvl(ASSETVALUE_B, 0))) avgRate2, decode(sum(nvl(VALUEA_LAST, 0)),0,0,SUM(avgRate1Last) / sum(nvl(VALUEA_LAST, 0))) avgRate1Last, decode(sum(nvl(VALUEB_LAST, 0)),0,0,SUM(avgRate2Last) / sum(nvl(VALUEB_LAST, 0))) avgRate2Last, MAX(heaverTimes1) heaverTimes1, MAX(heaverTimes2) heaverTimes2, /***信贷资产支持证券*/ sum(valueB01) valueB01, sum(valueBlast01) valueBlast01, /***资产支持专项计划*/ sum(valueB02) valueB02, sum(valueBlast02) valueBlast02 FROM ( SELECT AI.CONSTRACTE_BUSI_TYPE ||'_'||AI.CONSTRACTE_GRADE||'_'||DECODE(AI.ASSET_TYPE2,'1116','F01','F06') VALCODE, POS.ASSETVALUE_A, POS.ASSETVALUE_B, POS1.ASSETVALUE_A VALUEA_LAST, POS1.ASSETVALUE_B VALUEB_LAST, nvl(POS.ASSETVALUE_A,0)*nvl(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate1, nvl(POS.ASSETVALUE_B,0)*nvl(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate2, nvl(POS1.ASSETVALUE_A,0)*nvl(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate1Last, nvl(POS1.ASSETVALUE_B,0)*nvl(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate2Last, CASE WHEN POS.ASSET_CODE IS NOT NULL THEN AI.CONSTRACTE_HEAVER_TIMES ELSE 0 END heaverTimes1, CASE WHEN POS1.ASSET_CODE IS NOT NULL THEN AI.CONSTRACTE_HEAVER_TIMES ELSE 0 END heaverTimes2, /***信贷资产支持证券*/ decode(AI.CHB_SECTYPE,'22',nvl(POS.ASSETVALUE_B,0),0) valueB01, decode(AI.CHB_SECTYPE,'22',nvl(POS1.ASSETVALUE_B,0),0) valueBlast01, /***资产支持专项计划*/ decode(AI.CHB_SECTYPE,'23',nvl(POS.ASSETVALUE_B,0),0) valueB02, decode(AI.CHB_SECTYPE,'23',nvl(POS1.ASSETVALUE_B,0),0) valueBlast02 FROM CHB_ASSET_INFO AI LEFT JOIN CHB_MONTH_ASSET_POSITION POS ON AI.ASSET_CODE = POS.ASSET_CODE and to_char(pos.enddate,'yyyyMM')= #{termId, jdbcType=VARCHAR} LEFT JOIN CHB_MONTH_ASSET_POSITION POS1 ON AI.ASSET_CODE = POS1.ASSET_CODE and to_char(pos1.enddate,'yyyyMM')= #{lastTermId, jdbcType=VARCHAR}
left join DATA_AUTH_NOTIFY_INST di on POS.PROD_ID=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
WHERE AI.STATUS IN ('E','M') and AI.ASSET_TYPE2 IN ('1116','2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1211','1212','1213','2202' ,'1299','1301','1399','2101','2617') and (POS.ASSET_CODE is not null or POS1.ASSET_CODE is not null
and di.institution_code=#{org, jdbcType=VARCHAR}
) ) A GROUP BY A.VALCODE

/*债券本季末数额*/ SELECT 'BONDCUR' AS reportType, mst.INDUSTRY AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie) = mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} AND INFO.ASSET_TYPE2 IN ('1113', '1114', '1115') AND mst.INDUSTRY IS NOT NULL and mst.INDUSTRY !='10'
and di.institution_code=#{org, jdbcType=VARCHAR}
GROUP BY mst.INDUSTRY
/*债券上季末数额*/ UNION ALL SELECT 'BONDLAST' AS reportType, mst.INDUSTRY AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie) = mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} AND mst.INDUSTRY is NOT NULL and mst.INDUSTRY !='10' AND INFO.ASSET_TYPE2 IN ('1113', '1114', '1115')
and di.institution_code=#{org, jdbcType=VARCHAR}
GROUP BY mst.INDUSTRY
/*非标准化债权类投资本季末数额*/ UNION ALL SELECT 'NOSTABONDCUR' AS reportType, mst.INDUSTRY AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie) = mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE}
AND (INFO.ASSET_TYPE2 IN ('2101', '1211','1212','1213','2202', '2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1211','1212','1213') OR (INFO.ASSET_TYPE2 ='1299' and INFO.IN_ASSET_TYPE is not null AND INFO.IN_ASSET_TYPE NOT IN ('01','02')) OR (INFO.ASSET_TYPE2 ='1299' AND INFO.IN_ASSET_TYPE is null)) AND mst.INDUSTRY is not null
and di.institution_code=#{org, jdbcType=VARCHAR}
GROUP BY mst.INDUSTRY
/*非标准化债权类投资上季末数额*/ UNION ALL SELECT 'NOSTABONDLAST' AS reportType, mst.INDUSTRY AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie) = mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE}
AND (INFO.ASSET_TYPE2 IN ('2101', '1211','1212','1213','2202', '2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1211','1212','1213') OR (INFO.ASSET_TYPE2 ='1299' and INFO.IN_ASSET_TYPE is not null AND INFO.IN_ASSET_TYPE NOT IN ('01','02')) OR (INFO.ASSET_TYPE2 ='1299' AND INFO.IN_ASSET_TYPE is null)) AND mst.INDUSTRY IS NOT NULL
and di.institution_code=#{org, jdbcType=VARCHAR}
GROUP BY mst.INDUSTRY
/* 其他本季末数额 */ UNION ALL SELECT 'OTHERCUR' AS reportType, '10' AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie)=mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} AND (CMAP.assettype2 IN ('1001', '1002', '1003', '1004','1005','2501','2502','1107','1108') or (mst.INDUSTRY ='10' AND INFO.ASSET_TYPE2 IN ('1113', '1114', '1115') ))
and di.institution_code=#{org, jdbcType=VARCHAR}
/* 其他上季末数额 */ UNION ALL SELECT 'OTHERLAST' AS reportType, '10' AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie)=mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} AND (CMAP.assettype2 IN ('1001', '1002', '1003', '1004','1005','2501','2502','1107','1108') or (mst.INDUSTRY ='10' AND INFO.ASSET_TYPE2 IN ('1113', '1114', '1115') ))
and di.institution_code=#{org, jdbcType=VARCHAR}

/*债券本季末数额*/ select t.* from (SELECT 'BONDCUR' AS reportType, d1.item_value AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie)=mst.customer_id left join sys_datadict_list d1 on mst.province=d1.item_code and d1.dict_code ='ADMINISTRATIVE_TYPE' WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.manager_id,info.financie) is not null AND mst.province IS NOT NULL and info.asset_type2 in ('1101','1110','1109','1111','1102','1112','1113','1114','1115','1116','1117')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
and di.institution_code=#{org, jdbcType=VARCHAR}
GROUP BY d1.item_value )t where 1=1
and t.balance!=0
