/*产业投资基金本季末余额*/ UNION ALL select t.* from (SELECT 'INDINCUR' AS reportType, d1.item_value AS propertyCode, NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP
